export function ActivityLogPage() {
  const [entityType, setEntityType] = useState("");
  const input = useMemo(() => ({ entityType: entityType || undefined, limit: 300 }), [entityType]);
  const activity = trpc.court.activityLog.useQuery(input);
  const labelFor = (action: string) => activityLabels[action] || action.replaceAll("_", " ").replaceAll(".", " · ");
  const exportRows = () => (activity.data ?? []).map(item => ({ action: labelFor(item.audit.action), actor: item.actorName || "النظام الآلي", entity: `${item.audit.entityType}${item.audit.entityId ? ` #${item.audit.entityId}` : ""}`, at: new Date(item.audit.createdAt).toLocaleString("ar-SA") }));
  const exportExcel = () => {
    const rows = exportRows();
    const html = `<table dir="rtl"><tr><th>الإجراء</th><th>المنفذ</th><th>الكيان</th><th>الوقت</th></tr>${rows.map(row => `<tr><td>${row.action}</td><td>${row.actor}</td><td>${row.entity}</td><td>${row.at}</td></tr>`).join("")}</table>`;
    const link = document.createElement("a");
    link.href = URL.createObjectURL(new Blob([`\uFEFF<html><meta charset="utf-8">${html}</html>`], { type: "application/vnd.ms-excel" }));
    link.download = "سجل-الحركة.xls";
    link.click();
    URL.revokeObjectURL(link.href);
  };
  const exportPdf = () => {
    window.print();
  };
  return <DashboardLayout><section className="mx-auto max-w-6xl"><ScreenHeader eyebrow="عرض قيادي موحد" title="سجل الحركة" description="سجل تدقيق زمني لكل العمليات التشغيلية، يوضح الحساب المنفذ والعملية والكيان المرتبط بها وتاريخ التنفيذ ووقته." icon={ScrollText} /><div className="mt-6 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#e7e0d4] bg-white p-4"><label className="text-sm font-bold text-[#53675d]">تصفية حسب نوع الكيان<select value={entityType} onChange={event => setEntityType(event.target.value)} className="mr-3 h-10 rounded-md border border-input bg-transparent px-3 text-sm font-normal"><option value="">كل العمليات</option><option value="task">المهام</option><option value="delay">المتعثرات</option><option value="correspondence">المراسلات</option><option value="leave_request">الإجازات والاستئذان</option><option value="attendance">الحضور والانصراف</option><option value="person_profile">ملفات الأفراد</option><option value="registration_request">طلبات التسجيل</option><option value="administrative_level">التسلسل الإداري</option></select></label><div className="flex items-center gap-2"><button type="button" onClick={exportExcel} className="rounded-xl border px-3 py-2 text-xs font-black">تصدير Excel</button><button type="button" onClick={exportPdf} className="rounded-xl bg-[#12352f] px-3 py-2 text-xs font-black text-white">تصدير PDF</button><p className="text-xs text-[#74847b]">يعرض آخر 300 حركة مسجلة.</p></div></div><div className="mt-5 overflow-hidden rounded-[1.5rem] border border-[#e7e0d4] bg-white shadow-[0_10px_30px_rgba(30,51,42,0.05)]">{activity.isLoading ? <div className="flex items-center gap-2 p-7 text-sm text-[#6e7e75]"><CircleDashed className="h-4 w-4 animate-spin" /> جارٍ تحميل سجل الحركة…</div> : activity.data?.length ? <div className="divide-y divide-[#eee8de]">{activity.data.map(item => <article key={item.audit.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div className="min-w-0"><p className="font-bold text-[#29463b]">{labelFor(item.audit.action)}</p><p className="mt-1 text-xs text-[#75837c]">الكيان: {item.audit.entityType}{item.audit.entityId ? ` · رقم ${item.audit.entityId}` : ""}</p>{item.audit.metadata && <p className="mt-1 truncate text-xs text-[#8b8174]">التفاصيل: {item.audit.metadata}</p>}</div><div className="shrink-0 text-right"><p className="text-sm font-bold text-[#395b4c]">{item.actorName || "النظام الآلي"}</p><p className="mt-1 text-xs text-[#75837c]">{new Date(item.audit.createdAt).toLocaleString("ar-SA", { dateStyle: "medium", timeStyle: "short" })}</p></div></article>)}</div> : <Empty text="لا توجد حركات مطابقة للتصفية الحالية." />}<ErrorBlock error={activity.error} /></div></section></DashboardLayout>;
}
